<?php
declare(strict_types=1);requireRole('subject-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='request-goods';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$items=$divisions=$requests=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$itemId=filter_input(INPUT_POST,'item_id',FILTER_VALIDATE_INT);$quantity=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);$divisionId=filter_input(INPUT_POST,'ds_division_id',FILTER_VALIDATE_INT);$justification=trim((string)($_POST['justification']??''));if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$itemId)$errors[]='Select an inventory item.';if(!$quantity||$quantity<1)$errors[]='Quantity must be at least one.';if(!$divisionId)$errors[]='Select a destination DS Division.';if(mb_strlen($justification)<10||mb_strlen($justification)>1000)$errors[]='Provide a justification between 10 and 1000 characters.';if(!$errors){try{$check=database()->prepare("SELECT i.id FROM inventory_items i JOIN ds_divisions ds ON ds.id=:ds WHERE i.id=:item AND ds.status='active'");$check->execute(['item'=>$itemId,'ds'=>$divisionId]);if(!$check->fetch())throw new RuntimeException('The selected item or destination is unavailable.');$s=database()->prepare('INSERT INTO goods_requests(item_id,quantity,destination_ds_division_id,justification,requested_by) VALUES(:item,:quantity,:division,:justification,:user)');$s->execute(['item'=>$itemId,'quantity'=>$quantity,'division'=>$divisionId,'justification'=>$justification,'user'=>$_SESSION['user_id']]);$id=(int)database()->lastInsertId();logActivity('Goods Requests','Submitted goods request','GR-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),'pending');$_SESSION['flash_success']='Goods request submitted for Admin approval.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=request-goods');exit;}catch(Throwable $e){error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to submit goods request.';}}}
try{$items=database()->query('SELECT id,item_name,variety,quantity FROM inventory_items ORDER BY item_name,variety')->fetchAll();$divisions=database()->query("SELECT ds.id,CONCAT(d.name,' — ',ds.name) name FROM ds_divisions ds JOIN districts d ON d.id=ds.district_id WHERE ds.status='active' ORDER BY d.name,ds.name")->fetchAll();$s=database()->prepare('SELECT g.*,i.item_name,i.variety,ds.name division_name,u.full_name approver_name FROM goods_requests g JOIN inventory_items i ON i.id=g.item_id JOIN ds_divisions ds ON ds.id=g.destination_ds_division_id LEFT JOIN users u ON u.id=g.approved_by WHERE g.requested_by=:user ORDER BY g.id DESC');$s->execute(['user'=>$_SESSION['user_id']]);$requests=$s->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$errors[]='Goods workflow is unavailable. Import database/migration_goods_workflow.sql.';}
$labels=['pending-admin-approval'=>'Pending Admin Approval','approved-awaiting-dispatch'=>'Approved — Awaiting Dispatch','dispatched'=>'Dispatched','rejected'=>'Rejected'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request Goods from Store | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Request Goods from Store</h1></div></header><main class="dashboard-content goods-workflow-page"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>New Goods Request</h2></div><form method="post" class="goods-request-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><div class="goods-request-grid"><label>Item and Variety<select name="item_id" required><option value="">Select item</option><?php foreach($items as $item):?><option value="<?=(int)$item['id']?>"><?=htmlspecialchars($item['item_name'].($item['variety']?' — '.$item['variety']:'').' (central stock: '.$item['quantity'].')',ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" min="1" required></label><label>Destination DS Division<select name="ds_division_id" required><option value="">Select division</option><?php foreach($divisions as $d):?><option value="<?=(int)$d['id']?>"><?=htmlspecialchars($d['name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></div><label class="goods-full">Justification<textarea name="justification" rows="2" maxlength="1000" required></textarea></label><button class="admin-primary-action">Submit Request</button></form></section><section class="admin-data-card goods-list-card"><div class="admin-data-header"><h2>My Goods Requests</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table goods-table"><thead><tr><th>ID</th><th>Item</th><th>Qty</th><th>Destination</th><th>Submitted</th><th>Status</th><th>Approved By</th><th>Reason</th></tr></thead><tbody><?php if(!$requests):?><tr><td colspan="8" class="admin-empty-row">No goods requests available.</td></tr><?php else:foreach($requests as $r):?><tr><td>GR-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?></td><td><?=(int)$r['quantity']?></td><td><?=htmlspecialchars($r['division_name'],ENT_QUOTES,'UTF-8')?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?=htmlspecialchars($labels[$r['status']],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['approver_name']?:'—',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['rejection_reason']?:'—',ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
